# Autogenerated strategy combining MACD crossover entries with ATR-based trailing stops
# Exports: compute_indicators, order_func

from typing import Any, Dict, Tuple

import numpy as np
import pandas as pd


def compute_indicators(
    ohlcv: pd.DataFrame,
    macd_fast: int = 12,
    macd_slow: int = 26,
    macd_signal: int = 9,
    sma_period: int = 50,
    atr_period: int = 14,
) -> Dict[str, np.ndarray]:
    """
    Compute indicators required by the strategy.

    Returns a dictionary with keys:
      - 'close': np.ndarray
      - 'high': np.ndarray
      - 'macd': np.ndarray  (MACD line)
      - 'signal': np.ndarray (MACD signal line)
      - 'atr': np.ndarray
      - 'sma': np.ndarray

    The function is written to avoid lookahead bias: all indicators use only
    current and past information.
    """
    # Input validation
    if not isinstance(ohlcv, pd.DataFrame):
        raise TypeError("ohlcv must be a pandas DataFrame")

    # Ensure required columns exist
    for col in ["close", "high", "low"]:
        if col not in ohlcv.columns:
            raise KeyError(f"ohlcv must contain '{col}' column")

    close = ohlcv["close"].astype(float).copy()
    high = ohlcv["high"].astype(float).copy()
    low = ohlcv["low"].astype(float).copy()

    # MACD: EMA fast - EMA slow, signal = EMA(macd)
    # Use EWM with adjust=False to emulate classic EMA
    ema_fast = close.ewm(span=macd_fast, adjust=False).mean()
    ema_slow = close.ewm(span=macd_slow, adjust=False).mean()
    macd_line = ema_fast - ema_slow
    signal_line = macd_line.ewm(span=macd_signal, adjust=False).mean()

    # ATR: True Range then rolling mean (min_periods=1 to avoid NaNs early)
    prev_close = close.shift(1)
    tr1 = high - low
    tr2 = (high - prev_close).abs()
    tr3 = (low - prev_close).abs()
    tr = pd.concat([tr1, tr2, tr3], axis=1).max(axis=1)
    atr = tr.rolling(window=atr_period, min_periods=1).mean()

    # SMA for trend filter
    sma = close.rolling(window=sma_period, min_periods=1).mean()

    # Convert to numpy arrays
    return {
        "close": close.values,
        "high": high.values,
        "macd": macd_line.values,
        "signal": signal_line.values,
        "atr": atr.values,
        "sma": sma.values,
    }


def order_func(
    c: Any,
    close: np.ndarray,
    high: np.ndarray,
    macd: np.ndarray,
    signal: np.ndarray,
    atr: np.ndarray,
    sma: np.ndarray,
    trailing_mult: float = 2.0,
) -> Tuple[float, int, int]:
    """
    Order function for vectorbt.from_order_func (use_numba=False).

    Logic implemented without lookahead: it simulates the strategy from the
    beginning up to the current index c.i and returns the order to be executed
    at time index c.i.

    Returns a tuple (size, size_type, direction). We use SizeType.Target (1)
    semantics for opening/closing positions by targeting 1 (long) or 0 (flat).

    Notes:
    - size_type=1 (Target), direction=1 (Long) are used to open/close long
      positions (target long size). These are integer codes consumed by the
      runner's wrapper; they avoid importing vectorbt enums here.
    - When there is no order at the current timestamp, return (np.nan, 0, 0)
      so the wrapper produces a no-op order.
    """
    # Basic sanity
    i = int(getattr(c, "i", 0))
    # Defensive: ensure arrays are numpy and have appropriate length
    close = np.asarray(close, dtype=float)
    high = np.asarray(high, dtype=float)
    macd = np.asarray(macd, dtype=float)
    signal = np.asarray(signal, dtype=float)
    atr = np.asarray(atr, dtype=float)
    sma = np.asarray(sma, dtype=float)

    n = len(close)
    if i < 0:
        # Should not happen, but handle gracefully
        return (np.nan, 0, 0)
    if i >= n:
        # Out-of-bounds index
        return (np.nan, 0, 0)

    # Constants for returned tuple (use integer codes)
    SIZE_TYPE_TARGET = 1  # SizeType.Target
    DIRECTION_LONG = 1    # Direction.Long

    # State simulation up to index i
    in_position = False
    entry_high = -np.inf

    # We'll iterate from t=1 to i (since cross checks need t-1)
    # But allow t=0 as potential entry if conditions permit (though cross won't trigger)
    for t in range(0, i + 1):
        # Helper: check macd cross up at t
        def is_cross_up(idx: int) -> bool:
            if idx == 0:
                return False
            a, b = macd[idx], signal[idx]
            a_prev, b_prev = macd[idx - 1], signal[idx - 1]
            if np.isnan(a) or np.isnan(b) or np.isnan(a_prev) or np.isnan(b_prev):
                return False
            return (a > b) and (a_prev <= b_prev)

        def is_cross_down(idx: int) -> bool:
            if idx == 0:
                return False
            a, b = macd[idx], signal[idx]
            a_prev, b_prev = macd[idx - 1], signal[idx - 1]
            if np.isnan(a) or np.isnan(b) or np.isnan(a_prev) or np.isnan(b_prev):
                return False
            return (a < b) and (a_prev >= b_prev)

        if not in_position:
            # Entry: MACD cross up AND price > SMA
            if is_cross_up(t):
                # Ensure price and sma are valid
                if not np.isnan(close[t]) and not np.isnan(sma[t]) and close[t] > sma[t]:
                    # Enter long: target size 1
                    if t == i:
                        return (1.0, SIZE_TYPE_TARGET, DIRECTION_LONG)
                    in_position = True
                    entry_high = high[t] if not np.isnan(high[t]) else -np.inf
        else:
            # Update highest since entry using current high
            if not np.isnan(high[t]):
                if high[t] > entry_high:
                    entry_high = high[t]
            # Compute stop price at t using current ATR
            stop_price = -np.inf
            if not np.isnan(entry_high) and not np.isnan(atr[t]):
                stop_price = entry_high - trailing_mult * atr[t]
            # Exit conditions: MACD cross down OR price falls below trailing stop
            cross_down = is_cross_down(t)
            price_below_stop = (not np.isnan(close[t])) and (stop_price != -np.inf) and (close[t] < stop_price)
            if cross_down or price_below_stop:
                # Exit to flat: target size 0
                if t == i:
                    return (0.0, SIZE_TYPE_TARGET, DIRECTION_LONG)
                in_position = False
                entry_high = -np.inf

    # If no order at this time
    return (np.nan, 0, 0)
